def steps(labels, selected):
    return '<div class="s001-stepper"><div class="s001-step-line"></div>'+''.join(f'<button type="button" class="s001-step {"selected" if i==selected else ""}" onclick="setStep({i})" aria-label="選擇 {escape(d)}"><span class="s001-step-dot">{("<span class=\"s001-step-inner\"></span>" if i==selected else "")}</span><span class="s001-step-text">{escape(d)}</span></button>' for i,d in enumerate(labels))+'</div>'

def ticket(header='這週學習安排',left='第 2 週',right='資料模型',code='W02',footer='每日 45 分鐘 · 週末練習'):
    return f'<div class="s001-ticket"><div class="s001-ticket-top"><span>{header}</span><span>{code}</span></div><div class="s001-ticket-body"><div><small>目前進度</small><strong>{left}</strong></div><div class="s001-ticket-track">••• ➜</div><div><small>本週目標</small><strong>{right}</strong></div></div><p class="s001-ticket-note">{footer}</p></div>'

def summary(label='W2',text='模型關聯＋DAX 基礎',meta='本週重點'):
    return f'<div class="s001-summary"><div class="s001-summary-picture">{scene}</div><div><small>{label}</small><strong>{text}</strong><span>{meta}</span></div></div>'

def timeline(items=None):
    items=items or [('09:00','練習資料模型'),('10:30','認識 DAX 語法'),('15:30','完成 10 題測驗')]
    return '<div class="s001-timeline">'+''.join(f'<div class="s001-event"><span class="s001-time">{t}</span><div class="s001-node-col"><span class="s001-node"></span></div><div class="s001-event-data"><div class="s001-activity">{v}</div></div></div>' for t,v in items)+'</div>'

sketches={
'C01':f'<div class="s001-sketch-hero">{scene}<div class="s001-sketch-caption"><strong>30 天學習計畫</strong><span>21 天</span></div></div>',
'C02':'<div class="s001-sketch-nav"><div class="s001-mark">✳</div><span>總覽</span><span class="active">每週計畫</span><span>學習素材</span></div>',
'C03':ticket(),
'C04':'<div class="s001-stepper"><div class="s001-step-line"></div>'+''.join(f'<span class="s001-step {"selected" if i==1 else ""}"><span class="s001-step-dot"></span><span class="s001-step-text">W{i+1}</span></span>' for i in range(4))+'</div>',
'C05':summary(),
'C06':timeline(),
'C07':'<div class="s001-activity-demo"><div class="s001-activity">完成今日 DAX 練習</div><div class="s001-activity">整理重點筆記</div></div>',
'C08':'<div class="s001-pill-demo"><span class="s001-pill yellow">練習</span><span class="s001-pill sky">影片</span><span class="s001-pill sage">筆記</span></div>',
'C09':'<div class="s001-countdown">✦ 距離模擬考 21 天</div>',
}
board=''.join(f'<article class="s001-board-card"><div class="s001-card-heading"><span>{id}</span><span>DRAWN COMPONENT</span></div><div class="s001-sketch">{sketches[id]}</div><div class="s001-card-info"><strong>{name}</strong><small>{subtitle}</small></div></article>' for id,name,subtitle in styles)

variants=[
 {'name':'PL-300 學習計畫','head':'30 天 Power BI 挑戰','desc':'把準備考試拆成每天做得到的小任務','badge':'距離模擬考 21 天','ticket':'本週學習進度','a':'第 2 週','b':'資料模型','phase':['W1','W2','W3','W4'],'summary':'模型關聯＋DAX 基礎','events':[('09:00','回顧星型模型'),('10:30','建立模型關聯'),('13:00','練習 CALCULATE'),('15:30','完成 10 題模擬考')]},
 {'name':'新人到職','head':'新人的第一個月','desc':'用清楚的步驟認識團隊、流程與任務','badge':'到職第 8 天','ticket':'這週的到職任務','a':'團隊介紹','b':'首個任務','phase':['W1','W2','W3','W4'],'summary':'與導師完成首次任務','events':[('09:30','與導師確認本週目標'),('10:30','取得工作工具權限'),('13:30','完成引導任務'),('16:00','寫下今日問題')]},
 {'name':'生活小練習','head':'七日生活小練習','desc':'讓每一個小目標都更容易開始','badge':'連續第 3 天','ticket':'今日小目標','a':'完成 2 件','b':'伸展 10 分','phase':['一','二','三','四','五'],'summary':'休息一下，補充能量','events':[('08:30','喝一杯水'),('12:00','午間散步'),('17:00','伸展肩頸'),('21:30','記錄今天的一件好事')]}
]

shell='''*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,'Noto Sans TC','PingFang TC',sans-serif;background:#f7f7f3;color:#27352b}button,input,textarea{font:inherit}button{cursor:pointer}button:focus-visible{outline:3px solid #b06a50;outline-offset:3px}.offline-shell{max-width:1310px;margin:auto;padding:30px 38px 90px}.offline-top{display:flex;gap:20px;align-items:center;justify-content:space-between;border-bottom:1px solid #dce3da;padding-bottom:22px}.offline-logo{font-family:Georgia,serif;font-size:32px}.offline-pill{border-radius:99px;padding:9px 13px;background:#e7eae0;font-size:11px;letter-spacing:1px}.offline-hero{padding:34px 0;display:flex;align-items:end;justify-content:space-between;gap:24px}.offline-hero h1{font-family:Georgia,serif;font-size:clamp(36px,4vw,54px);font-weight:400;line-height:1.1;margin:12px 0}.offline-hero h1 i{color:#a76550}.offline-hero p{font-size:13px;line-height:1.8;color:#718074;max-width:640px}.offline-tabs{display:flex;gap:8px;border-bottom:1px solid #dce3da;padding-bottom:15px;margin-bottom:20px}.offline-tabs button{border:1px solid #dce3da;border-radius:9px;padding:10px 15px;background:white;font-size:12px;color:#435548}.offline-tabs button.active{background:#25392d;color:white}.offline-columns{display:grid;grid-template-columns:1fr 480px;gap:25px;align-items:start}.offline-source{background:white;border:1px solid #dce2d7;border-radius:15px;padding:18px}.offline-source img{display:block;height:350px;width:100%;object-fit:contain;background:#f6f4ec;border-radius:12px}.offline-source h3{font-size:15px}.offline-source p{font-size:12px;line-height:1.7;color:#748075}.offline-modes{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.offline-modes button{background:white;border:1px solid #dce3d7;border-radius:10px;padding:10px 14px;font-size:12px}.offline-modes button.active{background:#f5ede7;border-color:#b77d5e;color:#754835}.offline-instructions{font-size:12px;color:#738073;line-height:1.7}.offline-device{width:100%;max-width:450px;background:#fbf9f1;border-radius:23px;border:1px solid #dce1d6;padding:19px;margin:0 auto}.offline-device h3{font-size:26px;margin:6px 0 10px;color:#363233}.offline-device p{font-size:12px;line-height:1.7}.offline-device .s001-scene-svg{background:#fefbf7;border:3px solid #363233;border-radius:19px;height:140px}.offline-device .s001-ticket{margin:14px 0 20px}.offline-device .s001-summary{margin:21px 0}.offline-device h4{color:#363233}.offline-explainer{background:#fff;border:1px solid #dce3d7;border-radius:12px;padding:16px;margin-top:20px;font-size:12px;line-height:1.75;color:#66766a}.offline-warning{margin-top:10px;color:#ab785b;font-size:11px}#offline-preview,#offline-ref{display:none}.offline-footer{font-size:12px;color:#8c998d;border-top:1px solid #dce3da;margin-top:40px;padding:30px 0}@media(max-width:850px){.offline-columns{grid-template-columns:1fr}.offline-shell{padding:18px 18px 50px}.offline-hero{padding:15px 0 20px}.offline-logo{font-size:25px}.offline-device{margin:0}.offline-source img{height:250px}}'''

html=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Design Archive v2 · STYLE-001 Offline Preview</title><style>{shell}\n{css}</style></head>
<body><div class="offline-shell"><header class="offline-top"><div class="offline-logo">Design Archive <span style="color:#b66c56">.</span></div><span class="offline-pill">V2 · OFFLINE PREVIEW</span></header><section class="offline-hero"><div><span class="s001-overline">STYLE-001 / PASTEL CARTOON TRAVEL PLANNER</span><h1>Learn a style.<br><i>Make something new.</i></h1><p>參考作品 → 設計規則 → 可重用元件 → 換內容後的版本。參考原圖和重新繪製的元件會分開管理。</p></div></section><nav class="offline-tabs"><button type="button" id="view-board" class="active" onclick="showTab('board')">01 元件展示板</button><button type="button" id="view-preview" onclick="showTab('preview')">02 換內容預覽</button><button type="button" id="view-ref" onclick="showTab('ref')">03 原始參考</button></nav>
<section id="offline-board"><div class="s001-section-title"><div><span class="s001-overline">9 EDITABLE COMPONENTS</span><h2>Component Board</h2><p>九個元件，使用全新的學習內容示範，不沿用原作品的釜山行程。</p></div><span class="s001-compact-tag">HTML · CSS · SVG</span></div><div class="s001-board">{board}</div></section>
<section id="offline-preview"><div class="s001-section-title"><div><span class="s001-overline">SAME DNA, NEW CONTENT</span><h2>Variation Preview</h2><p>選擇全新主題，觀察相同的元件系統如何承載不同內容。</p></div></div><div class="offline-modes">{''.join(f'<button type="button" id="mode{i}" class={"active" if i==0 else ""} onclick="switchVariant({i})">{escape(v["name"])}</button>' for i,v in enumerate(variants))}</div><div class="offline-columns"><div><p class="offline-instructions">右側預覽由這份離線 HTML 的元件即時切換示例資料。正式 Next.js 網站另外包含可生成 AI Prompt 的表單。</p><div class="offline-explainer">Design Archive v2 不會把原始旅遊內容直接換標題。這三組示範分別重建學習進度、到職成長路徑與生活習慣；同時保留淡彩、粗線框、階段節點及事件時間軸的設計語言。</div></div><div id="variant-target"></div></div></section>
<section id="offline-ref"><div class="s001-section-title"><div><span class="s001-overline">ORIGINAL REFERENCE · NOT COPIED</span><h2>Original Screenshot</h2><p>原作截圖僅作風格分析。來源網址僅為截圖中顯示的字樣，未獨立驗證。</p></div></div><div class="offline-source"><img src="{img_data}" alt="使用者提供的釜山行程網站截圖"><h3>來源圖與重新繪製的畫面分開</h3><p>截圖中可辨識 madori452.github.io，但尚未驗證。顏色與互動屬觀察和推論，不是原站 CSS。</p></div></section>
<div class="offline-footer">Design Archive v2 · Private Design Reference · 不含任何 API 呼叫 · 原作權利歸原作者</div></div><script>
const variants={json.dumps(variants,ensure_ascii=False)};let choice=0,activeStep=null;
function showTab(name){{for(const section of ['board','preview','ref']){{document.getElementById('offline-'+section).style.display=section===name?'block':'none'; document.getElementById('view-'+section).classList.toggle('active',section===name);}}}}
function switchVariant(index){{choice=index;activeStep=null;variants.forEach((_,i)=>document.getElementById('mode'+i).classList.toggle('active',i===index));drawVariant();}}
function setStep(index){{activeStep=index;drawVariant();}}
const scene={json.dumps(scene,ensure_ascii=False)};
function drawVariant(){{const v=variants[choice], stage=activeStep??1;
const stepper='<div class="s001-stepper"><div class="s001-step-line"></div>'+v.phase.map((s,i)=>'<button type="button" aria-pressed="'+(stage===i)+'" class="s001-step '+(stage===i?'selected':'')+'" onclick="setStep('+i+')"><span class="s001-step-dot">'+(stage===i?'<span class="s001-step-inner"></span>':'')+'</span><span class="s001-step-text">'+s+'</span></button>').join('')+'</div>';
const rows='<div class="s001-timeline">'+v.events.map(([time,label])=>'<div class="s001-event"><span class="s001-time">'+time+'</span><div class="s001-node-col"><span class="s001-node"></span></div><div class="s001-event-data"><div class="s001-activity">'+label+'</div></div></div>').join('')+'</div>';
document.getElementById('variant-target').innerHTML='<div class="offline-device">'+scene+'<div class="s001-hero-eyebrow">NEW SUBJECT · STYLE-001</div><h3>'+v.head+'</h3><p>'+v.desc+'</p><div class="s001-countdown">✦ '+v.badge+'</div><div class="s001-ticket"><div class="s001-ticket-top"><span>'+v.ticket+'</span><span>0'+(stage+1)+'</span></div><div class="s001-ticket-body"><div><small>目前進度</small><strong>'+v.a+'</strong></div><div class="s001-ticket-track">••➜</div><div><small>本週目標</small><strong>'+v.b+'</strong></div></div><p class="s001-ticket-note">新主題內容，而不是原作旅行資料</p></div><h4>階段選擇器</h4>'+stepper+'<div class="s001-summary"><div class="s001-summary-picture">'+scene+'</div><div><small>'+v.phase[stage]+'</small><strong>'+v.summary+'</strong><span>點擊上方節點切換階段</span></div></div>'+rows+'</div>';}}
showTab('board');drawVariant();
</script></body></html>'''
path=root/'PREVIEW_STYLE-001.html';path.write_text(html);print('Created',path, 'bytes',path.stat().st_size)
